#[inline]
fn sample_rgb(src:&[u8],width:usize,height:usize,x:f32,y:f32)->[u8;3]{let x=x.clamp(0.0,width.saturating_sub(1) as f32);let y=y.clamp(0.0,height.saturating_sub(1) as f32);let x0=x.floor() as usize;let y0=y.floor() as usize;let x1=(x0+1).min(width-1);let y1=(y0+1).min(height-1);let tx=x-x0 as f32;let ty=y-y0 as f32;let mut out=[0u8;3];for c in 0..3{let p00=src[(y0*width+x0)*3+c] as f32;let p10=src[(y0*width+x1)*3+c] as f32;let p01=src[(y1*width+x0)*3+c] as f32;let p11=src[(y1*width+x1)*3+c] as f32;let a=p00+(p10-p00)*tx;let b=p01+(p11-p01)*tx;out[c]=(a+(b-a)*ty).round().clamp(0.0,255.0) as u8;}out}
pub fn resize_rgb8(src:&[u8],width:usize,height:usize,out_w:usize,out_h:usize)->Vec<u8>{if width==0||height==0||out_w==0||out_h==0||src.len()<width*height*3{return Vec::new();}if width==out_w&&height==out_h{return src[..width*height*3].to_vec();}let mut out=vec![0u8;out_w*out_h*3];let sx=if out_w>1{(width-1) as f32/(out_w-1) as f32}else{0.0};let sy=if out_h>1{(height-1) as f32/(out_h-1) as f32}else{0.0};for oy in 0..out_h{for ox in 0..out_w{let p=sample_rgb(src,width,height,ox as f32*sx,oy as f32*sy);let i=(oy*out_w+ox)*3;out[i..i+3].copy_from_slice(&p);}}out}
pub fn down_up_rgb8(src:&[u8],width:usize,height:usize,scale:f32)->Vec<u8>{let scale=scale.clamp(0.01,1.0);let dw=((width as f32*scale).round() as usize).max(1);let dh=((height as f32*scale).round() as usize).max(1);let low=resize_rgb8(src,width,height,dw,dh);resize_rgb8(&low,dw,dh,width,height)}
pub fn crop_rgb8(src:&[u8],width:usize,height:usize,x0:usize,y0:usize,x1:usize,y1:usize)->(Vec<u8>,usize,usize){let x0=x0.min(width);let y0=y0.min(height);let x1=x1.min(width).max(x0);let y1=y1.min(height).max(y0);let cw=x1-x0;let ch=y1-y0;let mut out=vec![0u8;cw*ch*3];for y in 0..ch{let so=((y0+y)*width+x0)*3;let d=y*cw*3;out[d..d+cw*3].copy_from_slice(&src[so..so+cw*3]);}(out,cw,ch)}
